## Patterns to follow

**Provider wrapper (copy of `watchLoops`, src/agents/loop.ts:91-133), as `src/agents/idle.ts`:**
```typescript
import type { AgentEvent, AgentRun, Provider } from "../providers/types.js";

/** An agent printed nothing for too long and was stopped. */
export class IdleTimeoutError extends Error {
  constructor(message: string) {
    super(message);
    this.name = new.target.name;
  }
}

export function watchIdle(provider: Provider, minutes: number, onIdle?: (label: string, why: string) => void): Provider {
  if (minutes <= 0) return provider;
  const limitMs = minutes * 60_000;
  return {
    name: provider.name,
    run(opts): AgentRun {
      const own = new AbortController();
      const relay = (): void => own.abort(opts.signal.reason);
      if (opts.signal.aborted) own.abort(opts.signal.reason);
      else opts.signal.addEventListener("abort", relay, { once: true });
      const agent = provider.run({ ...opts, signal: own.signal });
      let idle: IdleTimeoutError | undefined;
      let timer: NodeJS.Timeout | undefined;
      const stop = (): void => { if (timer) clearTimeout(timer); timer = undefined; };
      const arm = (): void => {
        stop();
        timer = setTimeout(() => {
          const why = `it produced no output for ${minutes} minute${minutes === 1 ? "" : "s"}`;
          idle = new IdleTimeoutError(`the agent was stopped because ${why}`);
          onIdle?.(opts.label, why);
          own.abort(idle);
        }, limitMs);
        timer.unref();
      };
      arm();
      async function* events(): AsyncGenerator<AgentEvent> {
        try {
          for await (const event of agent.events) {
            if (!idle) arm();
            yield event;
          }
        } finally {
          stop();
          opts.signal.removeEventListener("abort", relay);
        }
      }
      const done = agent.done.then(
        (result) => { stop(); if (idle) throw idle; return result; },
        (err) => { stop(); throw idle ?? err; },
      );
      done.catch(() => {});
      return { events: events(), done };
    },
  };
}
```

**Wiring (src/runner/run.ts:259-266 today):**
```typescript
const provider = teeOutput(
  watchLoops(ctx.provider, config.loopDetection, (label, why) => {
    loopStops.push({ label, why });
    log(`[${label}] stopped: ${why}; retrying`);
  }),
  events,
);
```
becomes `teeOutput(watchIdle(watchLoops(...same...), config.idleTimeoutMinutes, (label, why) => log(\`[${label}] stopped: ${why}; retrying\`)), events)`. In e2e.ts / integrate.ts wrap the existing `watchLoops(env.provider, env.config.loopDetection, …)` in `watchIdle(…, env.config.idleTimeoutMinutes, (label, why) => log(\`[${label}] stopped: ${why}; retrying\`))`.

**Config key (mirror src/config/config.ts:30-36):**
```typescript
/**
 * Stops and retries an agent that produces no output for this many minutes (it counts as a failed attempt).
 * Fractions are allowed; 0 never stops an agent for silence.
 */
idleTimeoutMinutes: z.number().min(0).default(20),
```

**Line-capping execa transform (type-checked against execa 9.6.1 with this repo's tsconfig; verified at runtime, a 256 MiB line kept RSS at 75 MB):**
```typescript
import { StringDecoder } from "node:string_decoder";

/** Longest output line kept, in characters; the rest of a longer line is dropped and counted. */
export const MAX_LINE_CHARS = 1 << 20;

/** An execa binary transform that splits a stream into lines itself and truncates every line over `max` characters. */
export function capLines(max = MAX_LINE_CHARS) {
  const decoder = new StringDecoder("utf8");
  let pending = "";
  let dropped = 0;
  const take = (text: string): void => {
    const room = max - pending.length;
    if (text.length > room) {
      dropped += text.length - room;
      pending += text.slice(0, room);
    } else pending += text;
  };
  const line = (): string => {
    const out = dropped > 0 ? `${pending} [truncated ${dropped} characters]\n` : `${pending}\n`;
    pending = "";
    dropped = 0;
    return out;
  };
  return {
    binary: true,
    *transform(chunk: unknown): Generator<string> {
      let text = decoder.write(chunk as Buffer);
      for (let i = text.indexOf("\n"); i !== -1; i = text.indexOf("\n")) {
        take(text.slice(0, i));
        text = text.slice(i + 1);
        yield line();
      }
      take(text);
    },
    *final(): Generator<string> {
      take(decoder.end());
      if (pending !== "" || dropped > 0) yield line();
    },
  } as const;
}
```
and in `spawnAgent`'s execa options add `stdout: capLines(), stderr: capLines()` (one fresh transform per stream: each keeps its own partial line). With these, `iterable({ from: "all" })` gets whole lines from each stream, so stdout and stderr still interleave only at line boundaries. The line splitting is unchanged: verified that `"a\r\nb\n\néé…\nlast"` gives the same `["a","b","","éé…","last"]` with and without the transform.

**Byte-range read (src/web/logtail.ts:42-51):**
```typescript
const fh = await open(file, "r");
try {
  const buf = Buffer.alloc(Math.max(0, end - start));
  const { bytesRead } = await fh.read(buf, 0, buf.length, start);
  return buf.subarray(0, bytesRead);
} finally {
  await fh.close();
}
```

**Run-level test pattern (src/runner/run.test.ts:154-175):**
```typescript
const provider = createFakeProvider(fakeScriptSchema.parse({ "task:2": { attempts: [{ loop: 8 }] } }));
const { ctx, result } = await runDiamond(provider, undefined, { events });
expect(result.exitCode).toBe(0);
const state = await readState(ctx.runDir);
expect(state.tasks["2"]).toMatchObject({ status: "merged", attempts: 2 });
expect(lines).toContain('[2] stopped: …; retrying');
```
The retry line format is `task <id>: <reason.message>; retry <n>/<attempts>` (see run.test.ts lines 150–151).

**Naming / file conventions:** one concern per file under `src/agents/`, tests next to the source as `<name>.test.ts`, ESM imports with `.js` suffixes, error classes set `this.name = new.target.name`.

## Step-by-step tasks

### CREATE `src/agents/idle.ts`

- **IMPLEMENT**: `IdleTimeoutError` and `watchIdle(provider, minutes, onIdle?)` exactly as in "Patterns to follow". `minutes <= 0` returns `provider` itself. The timer is armed when `run()` is called and re-armed on every event; it is `unref()`ed and cleared when `done` settles or the events loop ends. Only the agent's own controller is aborted; the run's signal is untouched.
- **PATTERN**: `src/agents/loop.ts:91-133`.
- **IMPORTS**: `import type { AgentEvent, AgentRun, Provider } from "../providers/types.js";`
- **GOTCHA**: `done` must reject with the `IdleTimeoutError` even when the killed agent's `done` resolves normally (a killed fake/real agent resolves with exit code 1): that is what makes `withRetries` count it as `idle` and not as a plain `crash`. A run-level abort (Ctrl+C) must still behave as before: `idle` stays undefined, so `done` passes the result through.
